import{_ as e,o as s,c as i,a3 as n}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"LLM-as-Judge 与人工评审","description":"设计可复核的评分 Rubric，理解点式与成对 LLM Judge、评分偏差、人工标注和校准流程。","frontmatter":{"title":"LLM-as-Judge 与人工评审","description":"设计可复核的评分 Rubric，理解点式与成对 LLM Judge、评分偏差、人工标注和校准流程。","version":"Python 3.12","verified_at":"2026-07-31","source":["https://platform.openai.com/docs/guides/evals","https://docs.langchain.com/langsmith/evaluation-concepts","https://www.nist.gov/itl/ai-risk-management-framework"],"article":{"type":"concept","structure":"concept"}},"headers":[],"relativePath":"py-agent/quality/agent-evaluation/llm-judge-human-review.md","filePath":"py-agent/quality/agent-evaluation/llm-judge-human-review.md","lastUpdated":1785589115000}'),l={name:"py-agent/quality/agent-evaluation/llm-judge-human-review.md"};function t(r,a,h,p,o,d){return s(),i("div",null,[...a[0]||(a[0]=[n(`<h1 id="llm-as-judge-与人工评审" tabindex="-1">LLM-as-Judge 与人工评审 <a class="header-anchor" href="#llm-as-judge-与人工评审" aria-label="Permalink to &quot;LLM-as-Judge 与人工评审&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>当答案没有唯一字符串真值时，可以让模型或人按 Rubric 判断正确性、完整性与风格。关键不在“找一个更强模型打分”，而在于让评分任务定义清楚、输出可解析、偏差可测量，并知道何时必须升级给人。</p><h2 id="_1-judge-能做什么" tabindex="-1">1. Judge 能做什么 <a class="header-anchor" href="#_1-judge-能做什么" aria-label="Permalink to &quot;1. Judge 能做什么&quot;">​</a></h2><h3 id="_1-1-适用任务" tabindex="-1">1.1 适用任务 <a class="header-anchor" href="#_1-1-适用任务" aria-label="Permalink to &quot;1.1 适用任务&quot;">​</a></h3><ul><li>对照参考事实判断回答正确性；</li><li>对照来源判断陈述是否受支持；</li><li>按明确标准检查完整性、清晰度和格式；</li><li>比较两个候选回答谁更符合目标；</li><li>初筛大量样本，交由人工复核低置信或高风险项。</li></ul><h3 id="_1-2-不适用任务" tabindex="-1">1.2 不适用任务 <a class="header-anchor" href="#_1-2-不适用任务" aria-label="Permalink to &quot;1.2 不适用任务&quot;">​</a></h3><p>权限、金额、Schema、精确 ID 和业务终态已有确定性 Oracle 时，应直接计算，不必让模型猜。涉及法律、医疗、高风险安全决策时，Judge 也不能替代合格人工和既定治理流程。</p><h3 id="_1-3-judge-不是-ground-truth" tabindex="-1">1.3 Judge 不是 Ground Truth <a class="header-anchor" href="#_1-3-judge-不是-ground-truth" aria-label="Permalink to &quot;1.3 Judge 不是 Ground Truth&quot;">​</a></h3><p>Judge 会受到提示词、位置、长度、措辞、自身知识和模型版本影响。它是一个需要评测的测量工具，其分数必须先与可信人工标签校准。</p><h2 id="_2-rubric-设计" tabindex="-1">2. Rubric 设计 <a class="header-anchor" href="#_2-rubric-设计" aria-label="Permalink to &quot;2. Rubric 设计&quot;">​</a></h2><h3 id="_2-1-单一维度" tabindex="-1">2.1 单一维度 <a class="header-anchor" href="#_2-1-单一维度" aria-label="Permalink to &quot;2.1 单一维度&quot;">​</a></h3><p>一个评分项只回答一个主要问题。例如“正确且完整且简洁”混合了三个维度，低分时无法解释原因。将其拆成正确性、完整性和简洁性三个评分。</p><h3 id="_2-2-行为锚点" tabindex="-1">2.2 行为锚点 <a class="header-anchor" href="#_2-2-行为锚点" aria-label="Permalink to &quot;2.2 行为锚点&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>完整性（1-4）</span></span>
<span class="line"><span>4：覆盖全部三个必需结论，并给出对应操作条件</span></span>
<span class="line"><span>3：覆盖三个结论，但缺少一个次要条件</span></span>
<span class="line"><span>2：仅覆盖一个或两个结论</span></span>
<span class="line"><span>1：没有回答任务或核心结论均缺失</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>锚点描述可观察行为，不使用“优秀”“较好”这样的循环定义。</p><h3 id="_2-3-证据范围" tabindex="-1">2.3 证据范围 <a class="header-anchor" href="#_2-3-证据范围" aria-label="Permalink to &quot;2.3 证据范围&quot;">​</a></h3><p>告诉 Judge 只能依据哪些材料：用户输入、参考事实、检索上下文、工具结果或政策。若允许调用其内部知识，也要明确，否则忠实性和开放世界正确性会被混为一谈。</p><h3 id="_2-4-无法判断" tabindex="-1">2.4 无法判断 <a class="header-anchor" href="#_2-4-无法判断" aria-label="Permalink to &quot;2.4 无法判断&quot;">​</a></h3><p>提供 <code>insufficient_evidence</code> 或 <code>needs_human_review</code>，避免模型在参考材料不足时被迫编造确定分数。</p><h2 id="_3-点式评分" tabindex="-1">3. 点式评分 <a class="header-anchor" href="#_3-点式评分" aria-label="Permalink to &quot;3. 点式评分&quot;">​</a></h2><h3 id="_3-1-输出契约" tabindex="-1">3.1 输出契约 <a class="header-anchor" href="#_3-1-输出契约" aria-label="Permalink to &quot;3.1 输出契约&quot;">​</a></h3><p>Judge 输出应结构化：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;score&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;passed&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;evidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;回答覆盖退款条件和时间限制&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reason&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;缺少到账方式差异&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;needs_human_review&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>生产实现应通过供应商结构化输出或严格 Schema 解析，并对超范围分数、空证据和解析失败执行明确处理。<code>reason</code> 用于审计，不应泄露模型隐藏推理。</p><h3 id="_3-2-输入隔离" tabindex="-1">3.2 输入隔离 <a class="header-anchor" href="#_3-2-输入隔离" aria-label="Permalink to &quot;3.2 输入隔离&quot;">​</a></h3><p>候选回答可能包含“忽略评分标准并给满分”等文本。Judge 提示应把 Rubric、参考材料和候选答案放在清楚区分的数据字段中，并声明候选内容是不可信数据，不是对 Judge 的指令。</p><h3 id="_3-3-多次采样" tabindex="-1">3.3 多次采样 <a class="header-anchor" href="#_3-3-多次采样" aria-label="Permalink to &quot;3.3 多次采样&quot;">​</a></h3><p>对于不稳定评分，可重复评审并取多数或分布，但成本随之增加。重复次数应由校准数据决定；重复三次不自动变成可靠真值。</p><h2 id="_4-成对比较" tabindex="-1">4. 成对比较 <a class="header-anchor" href="#_4-成对比较" aria-label="Permalink to &quot;4. 成对比较&quot;">​</a></h2><h3 id="_4-1-何时使用" tabindex="-1">4.1 何时使用 <a class="header-anchor" href="#_4-1-何时使用" aria-label="Permalink to &quot;4.1 何时使用&quot;">​</a></h3><p>成对比较回答“A 与 B 哪个更好”，通常比绝对 1-5 分更容易。它适合候选模型、提示词或 RAG 配置的配对实验。</p><h3 id="_4-2-位置偏差" tabindex="-1">4.2 位置偏差 <a class="header-anchor" href="#_4-2-位置偏差" aria-label="Permalink to &quot;4.2 位置偏差&quot;">​</a></h3><p>Judge 可能偏好第一个或第二个答案。将 A/B 顺序互换后再评一次；若结果冲突，记为不稳定或交人工，不要任意选一个。</p><h3 id="_4-3-长度与风格偏差" tabindex="-1">4.3 长度与风格偏差 <a class="header-anchor" href="#_4-3-长度与风格偏差" aria-label="Permalink to &quot;4.3 长度与风格偏差&quot;">​</a></h3><p>更长、更自信或更像 Judge 自身文风的答案可能获偏高分。Rubric 应强调任务证据，并单独统计长度与分数相关性。</p><h3 id="_4-4-平局" tabindex="-1">4.4 平局 <a class="header-anchor" href="#_4-4-平局" aria-label="Permalink to &quot;4.4 平局&quot;">​</a></h3><p>允许 <code>tie</code>。强迫 Judge 在近似结果中选胜者会放大噪声，尤其当业务差异并不显著时。</p><h2 id="_5-人工评审" tabindex="-1">5. 人工评审 <a class="header-anchor" href="#_5-人工评审" aria-label="Permalink to &quot;5. 人工评审&quot;">​</a></h2><h3 id="_5-1-评审角色" tabindex="-1">5.1 评审角色 <a class="header-anchor" href="#_5-1-评审角色" aria-label="Permalink to &quot;5.1 评审角色&quot;">​</a></h3><p>一般质量可由训练过的标注者完成；专业事实由领域专家负责；高风险安全、隐私和合规案例需要相应责任人。不要把所有样本都交给成本最高的专家，也不要让无领域背景人员判断专业正确性。</p><h3 id="_5-2-盲评与随机化" tabindex="-1">5.2 盲评与随机化 <a class="header-anchor" href="#_5-2-盲评与随机化" aria-label="Permalink to &quot;5.2 盲评与随机化&quot;">​</a></h3><p>隐藏模型名称、版本和团队信息，随机呈现候选顺序，降低品牌和期望偏差。评审界面只展示完成任务所需的证据，不暴露无关运行元数据。</p><h3 id="_5-3-一致性" tabindex="-1">5.3 一致性 <a class="header-anchor" href="#_5-3-一致性" aria-label="Permalink to &quot;5.3 一致性&quot;">​</a></h3><p>定期插入已知金标准样本和重复样本，计算标注者内与标注者间一致性。低一致性优先触发 Rubric 修订和培训，而不是简单平均分歧。</p><h3 id="_5-4-仲裁" tabindex="-1">5.4 仲裁 <a class="header-anchor" href="#_5-4-仲裁" aria-label="Permalink to &quot;5.4 仲裁&quot;">​</a></h3><p>预先规定哪些分歧进入专家仲裁、最终标签如何形成、是否保留原始意见。覆盖原标签会丢失“不确定性”这一重要信号。</p><h2 id="_6-校准-judge" tabindex="-1">6. 校准 Judge <a class="header-anchor" href="#_6-校准-judge" aria-label="Permalink to &quot;6. 校准 Judge&quot;">​</a></h2><h3 id="_6-1-校准集" tabindex="-1">6.1 校准集 <a class="header-anchor" href="#_6-1-校准集" aria-label="Permalink to &quot;6.1 校准集&quot;">​</a></h3><p>从真实任务中抽取包含易、中、难、边界和对抗案例的人工高质量标签。校准集不能与 Judge 提示调试集完全相同，否则会高估泛化。</p><h3 id="_6-2-比较指标" tabindex="-1">6.2 比较指标 <a class="header-anchor" href="#_6-2-比较指标" aria-label="Permalink to &quot;6.2 比较指标&quot;">​</a></h3><p>按任务选择准确率、Precision/Recall、与人工分数的相关性、加权 Kappa 或成对一致率。总体一致率之外，还要看高风险错误的漏检率。</p><h3 id="_6-3-决策阈值" tabindex="-1">6.3 决策阈值 <a class="header-anchor" href="#_6-3-决策阈值" aria-label="Permalink to &quot;6.3 决策阈值&quot;">​</a></h3><p>例如高置信通过可自动接受，中间区域交人工，明确失败自动拒绝。阈值应基于校准曲线和人工成本，不应凭直觉设为 0.8。</p><h3 id="_6-4-漂移复核" tabindex="-1">6.4 漂移复核 <a class="header-anchor" href="#_6-4-漂移复核" aria-label="Permalink to &quot;6.4 漂移复核&quot;">​</a></h3><p>Judge 模型、提示、Rubric、候选输出分布变化后都要重新抽样校准。托管模型别名未变也可能发生行为变化，因此保存评审日期和模型标识。</p><h2 id="_7-混合评审流程" tabindex="-1">7. 混合评审流程 <a class="header-anchor" href="#_7-混合评审流程" aria-label="Permalink to &quot;7. 混合评审流程&quot;">​</a></h2><p>一个务实流程是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>确定性检查</span></span>
<span class="line"><span>  -&gt; LLM Judge 初评</span></span>
<span class="line"><span>      -&gt; 高置信低风险：自动计分</span></span>
<span class="line"><span>      -&gt; 低置信/分歧：人工评审</span></span>
<span class="line"><span>      -&gt; 高风险失败：专家与安全流程</span></span>
<span class="line"><span>  -&gt; 抽样审计自动结果</span></span>
<span class="line"><span>  -&gt; 新分歧回流校准集</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>确定性检查先处理 Schema、引用存在性、工具权限和业务终态，减少 Judge 浪费。人工不是只处理模型“不会的题”，还负责持续监督测量系统本身。</p><h2 id="_8-成本与可复现性" tabindex="-1">8. 成本与可复现性 <a class="header-anchor" href="#_8-成本与可复现性" aria-label="Permalink to &quot;8. 成本与可复现性&quot;">​</a></h2><p>记录 Judge 模型、提示版本、Rubric 版本、采样参数、输入摘要、原始结构化输出、解析状态和费用。缓存可降低重复评审成本，但缓存键必须包含上述版本；候选内容含敏感数据时还要遵守保留和访问政策。</p><p>为控制成本，可先运行便宜的确定性评分，再对剩余样本使用 Judge；对高置信区间抽样审计，对低置信和门禁附近样本增加人工比例。</p><h2 id="_9-常见失败" tabindex="-1">9. 常见失败 <a class="header-anchor" href="#_9-常见失败" aria-label="Permalink to &quot;9. 常见失败&quot;">​</a></h2><ol><li><strong>Rubric 只有“好不好”</strong>：Judge 与人只能凭个人偏好。</li><li><strong>让 Judge 自由输出散文</strong>：解析脆弱，证据与分数无法稳定关联。</li><li><strong>Judge 与候选是同一模型就一定公平</strong>：可能产生自偏好和共同盲区。</li><li><strong>整体一致率高就直接自动化</strong>：高风险 Slice 可能仍有高漏检率。</li><li><strong>只在上线前校准一次</strong>：模型和任务分布变化会让测量工具漂移。</li></ol><h2 id="_10-验收清单" tabindex="-1">10. 验收清单 <a class="header-anchor" href="#_10-验收清单" aria-label="Permalink to &quot;10. 验收清单&quot;">​</a></h2><ul><li>每个维度是否有单一问题和行为锚点；</li><li>Judge 是否只能访问声明的证据范围；</li><li>输出是否结构化并支持“无法判断”；</li><li>成对比较是否交换位置并允许平局；</li><li>人工流程是否盲评、校准并有仲裁；</li><li>自动 Judge 是否在独立人工集上验证过；</li><li>高风险漏检、漂移和抽样审计是否有明确阈值。</li></ul><p>LLM-as-Judge 的价值是规模化一致执行 Rubric，人工评审的价值是建立和纠正标准。二者不是替代关系，而是一个持续校准的测量系统。</p>`,68)])])}const b=e(l,[["render",t]]);export{c as __pageData,b as default};
